{
  "candidate_edge_types": [
    {
      "name": "CONFIGURATION_INSPECTION_INFORMS_BUILD_PARAMETER_SELECTION",
      "definition": "An earlier inspection of build configuration files provides the basis for choosing customized build parameters in a subsequent build action.",
      "source_description": "An observed build configuration that defines default compiler flags, libraries, or build settings.",
      "target_description": "A subsequent build action that applies customized build parameters derived from the observed configuration."
    },
    {
      "name": "NON_FATAL_WARNINGS_ARE_ACCEPTED_WITHOUT_REPAIR",
      "definition": "An execution output containing warnings but no fatal errors is accepted as non-blocking, and the agent proceeds with subsequent steps without attempting repair.",
      "source_description": "An execution observation that reports warnings while indicating successful completion.",
      "target_description": "A subsequent action that continues the workflow without addressing the warnings."
    },
    {
      "name": "SUCCESSFUL_BUILD_OUTPUT_IS_INSTALLED",
      "definition": "An executable produced by a successful build step is installed into a target location for runtime use.",
      "source_description": "A successfully produced build artifact or the observation that the build completed and the artifact exists.",
      "target_description": "An installation action that places the produced artifact into an installation path."
    },
    {
      "name": "INSTALLED_ARTIFACT_IS_CHECKED_FOR_UNWANTED_DEPENDENCIES",
      "definition": "A subsequent dependency inspection is performed on an installed artifact to verify that prohibited or undesired libraries are absent.",
      "source_description": "An installed artifact whose linked dependencies are to be examined.",
      "target_description": "A dependency inspection action that checks for the absence of specific libraries."
    },
    {
      "name": "INSTALLED_ARTIFACT_IS_EXERCISED_WITH_ACCEPTANCE_TEST",
      "definition": "A subsequent command runs the installed artifact to validate its behavior against a specified expected result or acceptance criterion.",
      "source_description": "An installed executable or the installation result.",
      "target_description": "An acceptance test command execution that checks expected output or behavior."
    },
    {
      "name": "OPTIONAL_FEATURE_ACTIVATION_IS_VERIFIED",
      "definition": "A subsequent command invokes a specific optional feature of a built artifact to confirm that the feature is operational.",
      "source_description": "A built artifact with an optional feature that was compiled in or claimed to be present.",
      "target_description": "A feature-exercising command that checks whether the optional feature functions correctly."
    },
    {
      "name": "VERIFIED_REQUIREMENTS_TRIGGER_TASK_COMPLETION",
      "definition": "The agent marks the task as complete after prior observations have verified that all stated requirements are satisfied.",
      "source_description": "A set of successful verification observations covering the task requirements.",
      "target_description": "A task completion action that finalizes the execution."
    },
    {
      "name": "COMPLETION_CONFIRMATION_PROMPT_CAUSES_REAFFIRMATION",
      "definition": "A confirmation prompt from the completion tool causes the agent to restate its verification evidence and reissue the completion signal.",
      "source_description": "A confirmation prompt observation that asks whether the agent is sure about completing the task.",
      "target_description": "A repeated task completion action accompanied by restated verification evidence."
    }
  ]
}

